<!doctype html><html><head><meta charset="utf-8"><title>Receipt {{ $payment->payment_reference }}</title><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;600&family=Inter:wght@400;600&display=swap" rel="stylesheet"><link href="{{ asset('css/puihaha.css') }}" rel="stylesheet"></head><body class="receipt-page"><div class="receipt"><div class="receipt-brand">PUIHAHA <small>LEARNING PLATFORM</small></div><h1>Payment receipt</h1><p class="muted">Thank you. Your payment has been recorded.</p><hr><div class="detail-list"><div><small>Receipt reference</small><strong>{{ $payment->payment_reference }}</strong></div><div><small>Transaction</small><strong>{{ $payment->transaction->reference_number }}</strong></div><div><small>Member</small><strong>{{ $payment->transaction->member->full_name }}</strong></div><div><small>Payment date</small><strong>{{ $payment->payment_date->format('F d, Y') }}</strong></div><div><small>Payment method</small><strong>{{ $payment->payment_method }}</strong></div></div><div class="receipt-total"><span>Amount received</span><strong>₱{{ number_format($payment->amount,2) }}</strong></div><button class="btn-primary w-100 mt-4" onclick="window.print()">Print receipt</button></div></body></html>
